#include "Reader.h"
#include "../../../Sources/AtomicImageWriter.h"
#include <RetroMediaLab/MediaEngine/Diagnostics.h>
namespace RetroMediaLab::MediaEngine::RawTape {
const WriterCapabilities& Writer::capabilities()const{using namespace TapePcm::Constants;static const WriterCapabilities caps{std::string(RawWriter),{std::string(RawFormat)},{std::string(RawExtension)},{RepresentationKind::Sequential},false};return caps;}
bool Writer::canWrite(const MediaDocument& document,std::string_view format,std::string_view extension)const{using namespace TapePcm::Constants;int channels=0,rate=0,bits=0,align=0;return document.mediaKind()==MediaKind::Tape&&document.representationInfo().representationKind()==RepresentationKind::Sequential&&format==RawFormat&&sameIdentifier(extension,RawExtension)&&TapePcm::tryProfile(document.metadata(),channels,rate,bits,align);}
std::future<std::vector<std::filesystem::path>> Writer::writeAsync(std::shared_ptr<const MediaDocument> document,std::filesystem::path path,std::string format,std::stop_token token)const{return std::async(std::launch::deferred,[document=std::move(document),path=std::move(path),format=std::move(format),token]{checkCancellation(token);if(!document)throw MediaError(DiagnosticCode::HardDiskRawNullDocument);const auto raw=path.extension().u8string();if(!Writer{}.canWrite(*document,format,std::string(raw.begin(),raw.end())))throw MediaError(DiagnosticCode::RawTapeWrite);const auto& parameters=document->mediaSource()->options().parameters;const auto bytes=TapePcm::encodeDocument(*document,TapePcm::readProfile(parameters?&*parameters:&document->metadata()),token);writeAtomicImage(path,[&](const auto& output,auto stop){checkCancellation(stop);output(bytes);},token);return std::vector<std::filesystem::path>{path};});}
}
